     1	type Item = { type: string; cursed?: boolean; enchantment?: number };
     2	type QuoteStep = { op: "quote"; items: Item[] };
     3	type Damage = { itemType: string; amount: number };
     4	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
     5	
     6	export type Scenario = {
     7	  customer: { yearsWithMHPCO: number };
     8	  steps: unknown[];
     9	};
    10	
    11	export type ScenarioResult = { results: object[] };
    12	
    13	// MHPCO price list: insurance value and base premium per item type
    14	const PRICE_LIST: Record<string, { insuranceValue: number; basePremium: number }> = {
    15	  sword: { insuranceValue: 1000, basePremium: 100 },
    16	  amulet: { insuranceValue: 600, basePremium: 60 },
    17	  staff: { insuranceValue: 800, basePremium: 80 },
    18	  potion: { insuranceValue: 400, basePremium: 40 },
    19	  rune: { insuranceValue: 250, basePremium: 25 },
    20	  moonstone: { insuranceValue: 250, basePremium: 25 },
    21	};
    22	
    23	const PROCESSING_FEE = 5;
    24	// A block of 3 alike components costs 60 G instead of 3 × 25 = 75 G
    25	const BLOCK_DISCOUNT = 15;
    26	
    27	// 10% surcharge, computed by division to stay in exact integer arithmetic
    28	const firstInsuranceSurcharge = (policyBasePremium: number): number => policyBasePremium / 10;
    29	
    30	// 20% discount for customers with MHPCO for at least 2 years, computed by division
    31	const loyaltyDiscount = (policyBasePremium: number, yearsWithMHPCO: number): number =>
    32	  yearsWithMHPCO >= 2 ? policyBasePremium / 5 : 0;
    33	
    34	// 15% discount on follow-up contracts, computed exactly without float multipliers
    35	const followUpDiscount = (policyBasePremium: number, isFollowUpContract: boolean): number =>
    36	  isFollowUpContract ? (policyBasePremium * 15) / 100 : 0;
    37	
    38	// Only final amounts are rounded, always in MHPCO's favor:
    39	// premiums are rounded up, payouts are rounded down
    40	const roundPremiumInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
    41	const roundPayoutInMHPCOsFavor = (payout: number): number => Math.floor(payout);
    42	
    43	const blockDiscountFor = (items: Item[], type: string): number => {
    44	  const count = items.filter((item) => item.type === type).length;
    45	  return count === 3 ? BLOCK_DISCOUNT : 0;
    46	};
    47	
    48	const componentBlockDiscounts = (items: Item[]): number =>
    49	  blockDiscountFor(items, "rune") + blockDiscountFor(items, "moonstone");
    50	
    51	const basePremiumOf = (item: Item): number => PRICE_LIST[item.type].basePremium;
    52	
    53	const totalBasePremium = (items: Item[]): number => {
    54	  const itemPremiums = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
    55	  return itemPremiums - componentBlockDiscounts(items);
    56	};
    57	
    58	// Sums a surcharge computed from each qualifying item's own base premium
    59	const perItemSurcharge = (
    60	  items: Item[],
    61	  applies: (item: Item) => boolean,
    62	  surchargeOf: (basePremium: number) => number,
    63	): number =>
    64	  items.filter(applies).reduce((sum, item) => sum + surchargeOf(basePremiumOf(item)), 0);
    65	
    66	// 50% of each cursed item's own base premium
    67	const curseSurcharge = (items: Item[]): number =>
    68	  perItemSurcharge(items, (item) => item.cursed === true, (premium) => premium / 2);
    69	
    70	// 30% of each highly enchanted item's own base premium
    71	const highEnchantmentSurcharge = (items: Item[]): number =>
    72	  perItemSurcharge(items, (item) => (item.enchantment ?? 0) >= 5, (premium) => (premium * 3) / 10);
    73	
    74	const assertKnownItemTypes = (items: Item[]): void => {
    75	  const unknownItem = items.find((item) => !(item.type in PRICE_LIST));
    76	  if (unknownItem) throw new Error(`Unknown item type: ${unknownItem.type}`);
    77	};
    78	
    79	const quotePremium = (
    80	  step: QuoteStep,
    81	  yearsWithMHPCO: number,
    82	  isFollowUpContract: boolean,
    83	): number => {
    84	  assertKnownItemTypes(step.items);
    85	  const policyBasePremium = totalBasePremium(step.items);
    86	  return roundPremiumInMHPCOsFavor(
    87	    policyBasePremium +
    88	      curseSurcharge(step.items) +
    89	      highEnchantmentSurcharge(step.items) +
    90	      firstInsuranceSurcharge(policyBasePremium) -
    91	      loyaltyDiscount(policyBasePremium, yearsWithMHPCO) -
    92	      followUpDiscount(policyBasePremium, isFollowUpContract) +
    93	      PROCESSING_FEE,
    94	  );
    95	};
    96	
    97	const DEDUCTIBLE = 100;
    98	
    99	const insuranceSum = (items: Item[]): number =>
   100	  items.reduce((sum, item) => sum + PRICE_LIST[item.type].insuranceValue, 0);
   101	
   102	// The total payout per policy is capped at twice the insurance sum
   103	const coverageCap = (items: Item[]): number => 2 * insuranceSum(items);
   104	
   105	const isClaim = (step: unknown): step is ClaimStep => (step as ClaimStep).op === "claim";
   106	
   107	// A damage to an item not covered by the policy rejects the whole claim
   108	const insuredItemFor = (damage: Damage, policyItems: Item[]): Item => {
   109	  const insuredItem = policyItems.find((item) => item.type === damage.itemType);
   110	  if (!insuredItem) throw new Error(`Damaged item is not insured: ${damage.itemType}`);
   111	  return insuredItem;
   112	};
   113	
   114	// Damage to a highly enchanted item (enchantment >= 8) is only reimbursed at 50%
   115	const reimbursableAmount = (damage: Damage, policyItems: Item[]): number =>
   116	  (insuredItemFor(damage, policyItems).enchantment ?? 0) >= 8 ? damage.amount / 2 : damage.amount;
   117	
   118	// Each damage is paid out minus the per-damage deductible, never below zero
   119	const damagePayout = (damage: Damage, policyItems: Item[]): number =>
   120	  Math.max(0, reimbursableAmount(damage, policyItems) - DEDUCTIBLE);
   121	
   122	const claimPayout = (step: ClaimStep, policyItems: Item[]): number =>
   123	  roundPayoutInMHPCOsFavor(
   124	    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policyItems), 0),
   125	  );
   126	
   127	const assertNonNegativeDamages = (damages: Damage[]): void => {
   128	  const negativeDamage = damages.find((damage) => damage.amount < 0);
   129	  if (negativeDamage) throw new Error(`Damage amount must not be negative: ${negativeDamage.amount}`);
   130	};
   131	
   132	// Each insured item can be damaged at most once per claim.
   133	// Uninsured types are left to insuredItemFor, which reports them as not insured.
   134	const assertNoMoreDamagesThanInsured = (damages: Damage[], policyItems: Item[]): void => {
   135	  const overclaimed = damages.find(({ itemType }) => {
   136	    const insuredCount = policyItems.filter((item) => item.type === itemType).length;
   137	    const damagedCount = damages.filter((d) => d.itemType === itemType).length;
   138	    return insuredCount > 0 && damagedCount > insuredCount;
   139	  });
   140	  if (overclaimed) throw new Error(`More ${overclaimed.itemType} damages than insured`);
   141	};
   142	
   143	// Pays the claim up to whatever is left of the policy's coverage cap
   144	const settleClaim = (step: ClaimStep, policyItems: Item[], alreadyPaidOut: number) => {
   145	  assertNonNegativeDamages(step.incident.damages);
   146	  assertNoMoreDamagesThanInsured(step.incident.damages, policyItems);
   147	  const capLeft = coverageCap(policyItems) - alreadyPaidOut;
   148	  const payout = Math.min(claimPayout(step, policyItems), capLeft);
   149	  return { payout, remainingCap: capLeft - payout };
   150	};
   151	
   152	// Every contract after the customer's first one is a follow-up contract
   153	const isFollowUpContract = (steps: unknown[], index: number): boolean =>
   154	  steps.slice(0, index).some((step) => !isClaim(step));
   155	
   156	export const runScenario = (scenario: Scenario): ScenarioResult => {
   157	  const paidOutPerPolicy = new Map<number, number>();
   158	  const results = scenario.steps.map((step, index) => {
   159	    if (isClaim(step)) {
   160	      const policy = scenario.steps[step.policy] as QuoteStep;
   161	      const alreadyPaidOut = paidOutPerPolicy.get(step.policy) ?? 0;
   162	      const settlement = settleClaim(step, policy.items, alreadyPaidOut);
   163	      paidOutPerPolicy.set(step.policy, alreadyPaidOut + settlement.payout);
   164	      return settlement;
   165	    }
   166	    return {
   167	      premium: quotePremium(
   168	        step as QuoteStep,
   169	        scenario.customer.yearsWithMHPCO,
   170	        isFollowUpContract(scenario.steps, index),
   171	      ),
   172	    };
   173	  });
   174	  return { results };
   175	};

